module collinear_checker(input clk, input rst_n, input start, input [7:0] point_x [0:15], input [7:0] point_y [0:15], output reg success, output reg done); reg [2:0] state; reg [7:0] registered_point_x [0:15]; reg [7:0] registered_point_y [0:15]; reg [3:0] check_idx; reg [4:0] num_points_reg; always @(posedge clk) begin if (!rst_n) begin state <= 3'b000; registered_point_x <= 16'b0; registered_point_y <= 16'b0; check_idx <= 4'b0000; num_points_reg <= 5'b00000; success <= 1'b0; done <= 1'b0; end else if (start) begin registered_point_x <= point_x; registered_point_y <= point_y; num_points_reg <= num_points; if (num_points_reg < 3) begin success <= 1'b1; done <= 1'b1; state <= 3'b101; end else begin state <= 3'b001; check_idx <= 4'b0010; end end end endmodule